      "summary": "本卷中惠那跟随护堂一同进入幽世，参与了与佑理一同向护堂传授罗摩真名的联系仪式。她在幽世与护堂建立深厚联系。回归现世后她为天丛云剑输送咒力，提升黑之劔的成形速度。在花宫维摩那最终战中，她使用人神合一秘术挥舞天丛云剑，以一刀砍向罗摩。在罗摩空手夺白刃接住天丛云时，她用左手拔出封印了帕拉斯·雅典娜的复仇之剑（短剑），成功砍中罗摩腹部释放雅典娜的诅咒。"
