      "label": "艾莉卡·布兰德里",
      "summary": "本卷中艾莉卡作为护堂的最初骑士全程参与决战。她在护堂从古代回到日本后提供重要支援，在木更津战场远处观望。返回东京后她巧妙接待罗翠莲，展现宫廷女主人风范。她与琍琍亚娜共同锻造封印帕拉斯·雅典娜的复仇之剑，提出用魔术改变雅典娜外形的计策。在花宫维摩那上她与琍琍亚娜齐声咏唱神圣言灵，用乌鲁斯拉格纳圣剑斩裂齐天大圣侧腹，成功退敌。"
