      "summary": "罗摩的亲弟弟，暗中守护兄长的从属神。外表与罗摩一模一样但肌肤是褐色。在罗摩与帕拉斯·雅典娜决斗时出现，试图代替兄长握住救世神刀助阵，被雅典娜以青炎烧为灰烬。但他拥有不死神性，灰烬化为人类手臂拔出了神刀。最终战中他再次出现，从箭筒中拿出金色箭矢意图射向东京，被罗摩喝止。他是代替罗摩承受一切扭曲的存在。终章中他在木更津沙滩上向大海悲恸呼喊兄长之名。"
