      "label": "复仇之剑",
      "summary": "艾莉卡和琍琍亚娜在琍琍亚娜的车库中共同锻造的魔剑。刃长约五十公分，铅色刀身上刻有'昔在、今在、以后永在的全能者'。锻造素材包括铁剑锈屑、古利比亚遗迹陶片、盐、水银、凝固蓝熔岩碎片。艾莉卡用炼铁术将帕拉斯·雅典娜化为的银蛇熔入剑中，琍琍亚娜以魔女术协助。清秋院惠那用此剑砍中罗摩腹部，释放雅典娜的诅咒，削减其从圣杯获得的咒力。"
