      "summary": "护堂十大化身的第三化身。召唤搬运太阳的白马从东方天际飞向西方，运来闪耀太阳的火焰。此招术只能对折磨民众的大罪人使用。第8章中护堂在地下坑道咏唱言灵——『不死的太阳啊，请赐予我闪耀的骏马』，从天空降下白马，将巨大蜈蚣烧成灰烬，附近整座山的三分之一到一半被爆破消失。莉莉娅娜旁白评价『弑神者拿出真本事一战，这样的灾害算轻微了』。"
