      "summary": "西藏神具，长约一尺的铁制短棒，两端各有三叉头。为大威德明王（怖畏金刚、佛法守护神、钢之军神）的武具，持有者可自在操纵雷电。英国探险家从西藏高原的古老僧院盗走后，布雷纳卿以高价购入。经布雷纳卿以自身寿命增幅后释放极大雷击，威力仍不及沃邦曾面对的三位一体天神随手一击的一成。罗濠以方术亲自飞往伦敦夺回此物。被艾西亚捡到后以咒力注入扔向裂缝，电击沃邦和罗濠。"
