      "label": "艾西亚夫人（爱莎）",
      "summary": "本卷第一短篇的主角兼第一人称叙事者。自称十七岁的普通少女，兴趣是做料理和旅行，职业是旅人。实则拥有可以进行时间旅行的神秘力量。本卷中她穿越到十四世纪欧洲中世纪，邂逅了黑王子爱德华。面对爱德华对其真实年龄的犀利质疑，她使出天花板塌陷的力量打断了对话并逃离。其言行中展现出对日本次文化（摩古达/摩西达、21世纪流行语）的了解，暗示其多次穿越到日本现代。"
